questionvariables.text:
/* Realistic boda boda rim radius: 17"-18" rims -> ~20cm to 24cm radius, steps of 1 */
r: rand_with_step(20, 24, 1);

/* Realistic tyre (rubber) thickness beyond the rim: 6cm to 10cm, steps of 1 */
Thickness: rand_with_step(6, 10, 1);
R: r + Thickness;

/* pi = 22/7 as used throughout this topic */
Pi_val: 22/7;

R_sq: R^2;
r_sq: r^2;
Radius_difference: R_sq - r_sq;

/* Area of rubber cross-section (annulus between tyre outer edge and rim) */
A: Pi_val * Radius_difference;
A_2dp: float(decimalplaces(A, 2));
